import random
def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    markov = {}
    for i in range(n - 1):
        key = (me[i], opp[i], opp[i + 1])
        markov[key] = markov.get(key, 0) + 1
    if n > 3:
        cooperation = sum(1 for x in opp if x == 'C') / n
        my_coop = sum(1 for x in me if x == 'C') / n
        last_opp = opp[-1]
        last_me = me[-1]
        if n >= 20:
            recent = opp[-10:]
            recent_c = sum(1 for x in recent if x == 'C')
            if recent_c >= 8:
                if last_opp == 'C':
                    return 'C'
                key = (last_me, last_opp, 'C')
                if markov.get(key, 0) >= markov.get((last_me, last_opp, 'D'), 0):
                    return 'C'
                return 'D'
            if recent_c <= 2:
                if last_opp == 'D':
                    return 'D'
                return 'C'
        if cooperation >= 0.85:
            return 'C'
        if cooperation <= 0.2:
            return 'D'
        if n % 7 == 6 and cooperation > 0.45:
            return 'D'
        if last_opp == 'C':
            return 'C'
        keyC = (last_me, last_opp, 'C')
        keyD = (last_me, last_opp, 'D')
        cC = markov.get(keyC, 0)
        cD = markov.get(keyD, 0)
        if cC > cD:
            return 'C'
        if cD > cC:
            return 'D'
        forgiveness = 0.35 + 0.4 * cooperation
        if rng.random() < forgiveness:
            return 'C'
        return 'D'
    if n == 1:
        if opp[0] == 'C':
            return 'C'
        return 'D'
    if n == 2:
        if opp[-1] == 'C':
            return 'C'
        return 'D'
    if opp[-1] == 'C':
        return 'C'
    return 'D'
